  str_n12_entrust_stage_desc_101505 = "Corrí a un parque con Eclipsites persiguiéndote de cerca. A medida que el día se convertía rápidamente en noche, los peligros crecían en el exterior. ¿Cómo deshacerse de los eclipses y llegar a casa de forma segura?",
