  str_n12_story_desc_2 = "La señorita Siobhan parecía preocupada y muy irritable. Mejor aléjate de ella...",
  str_n12_story_desc_3 = "Un par de hermanas buscaban a su droide perdido junto al río. ¿Ayuda o no?",
  str_n12_story_desc_4 = "No se pudo encontrar a su pequeño droide. Con suerte, las dos hermanas no estarían demasiado molestas por las malas noticias...",
