  str_n12_affix_des_5121300 = "Invoca una gran cantidad de tentaclaws en un lugar aleatorio al comienzo de cada ronda. Se encogerán bajo tierra una vez que finalice el enlace del jugador.",
  str_n12_affix_des_5121301 = "Tentaclaws son partes del cuerpo de Kittypus. Todo el daño que sufran se duplicará y pasará a Kittypus.",
