  str_n12_affix_des_5121313 = "Sus espinas duras pueden reducir el daño. Spikeyhog recibe el 40% del daño de los aurorianos cercanos y recibe el daño total cuando se alejan 4 grupos circundantes.",
  str_n12_affix_des_5121314 = "Inmune a Aturdido, Asustado, Paralizado y otros efectos de control",
  str_n12_affix_des_5121315 = "Inmune a quemaduras, hemorragias, envenenamiento y otros tipos de daño DoT",
