  str_n12_affix_des_5122314 = "Por cada Lumiwall asesinado, todos los demás enemigos en el campo restauran su propio HP por <color=#00F6FF>10%</color> de su Max HP.",
  str_n12_affix_des_5122315 = "Por cada Lumiwall asesinado, todos los demás enemigos en el campo restauran su propio HP por <color=#00F6FF>25%</color> de su Max HP.",
  str_n12_affix_des_5122316 = "Por cada Lumiwall asesinado, todos los demás enemigos en el campo restauran su propio HP por <color=#00F6FF>50%</color> de su Max HP.",
  str_n12_affix_des_5122317 = "Phorosion obtuvo Pranayama I: Al comienzo de cada ronda, actualice <color=#00F6FF>1</color> pila de Count Shield. Si el escudo de conteo dura hasta el final de la ronda, restaura HP por <color=#00F6FF>3%</color>",
  str_n12_affix_des_5122318 = "Phorosion obtuvo Pranayama II: Al comienzo de cada ronda, actualice <color=#00F6FF>3</color> montones de escudo de conde. Si queda algún escudo de conteo al final de la ronda, restaura HP por <color=#00F6FF>3%</color>",
  str_n12_affix_des_5122319 = "Phorosion obtuvo Pranayama III: Al comienzo de cada ronda, actualice <color=#00F6FF>5</color> montones de escudo de conde. Si queda algún escudo de conteo al final de la ronda, restaura HP por <color=#00F6FF>5%</color>",
  str_n12_affix_des_5122320 = "Phorosion obtuvo Life Drain I: Convert <color=#00F6FF>100%</color> del daño que causa a su HP.",
  str_n12_affix_des_5122321 = "Phorosion obtuvo Life Drain II: Convert <color=#00F6FF>200%</color> del daño que causa a su HP.",
  str_n12_affix_des_5122322 = "Phorosion obtuvo Life Drain III: Convert <color=#00F6FF>400%</color> del daño que causa a su HP.",
  str_n12_affix_des_5122323 = "Phorosion obtuvo Debilidad Invisible: Reduce el daño que sufre de Chain Combos. Cuanto más cerca esté de los aurorianos, mejor será el efecto de reducción. Se puede reducir hasta un 60% el daño cuando está justo al lado de los aurorianos.",
  str_n12_affix_des_5122324 = "Phorosion obtuvo el Escudo de movimiento: por cada mosaico que mueven los aurorianos, gana 1 acumulación de marca de aumento de DEF, que puede aumentar la DEF base en un 5%. Todas las pilas se eliminan al final de cada ronda.",
  str_n12_affix_des_5122401 = "ATK de Sinforma -<color=#00F6FF>15%</color> y DEF -<color=#00F6FF>30%</color>",
  str_n12_affix_des_5122402 = "El daño que recibe Formless del ataque normal, combos en cadena y habilidades activas -<color=#00F6FF>{1}%</color>",
  str_n12_affix_des_5122405 = "Eclipsites invocados têm ATK aumentado em <color=#00F6FF>{1}%</color> e DEF e HP máximos aumentados em <color=#00F6FF>{2}%</color>.",
  str_n12_affix_des_5122408 = "Sin forma obtenido <color=#00F6FF>Reanimación I</color>: Conviértete en invencible cuando su HP cae al 1% y restaura <color=#00F6FF>10%</color> de su HP máximo después.",
  str_n12_affix_des_5122409 = "Sin forma obtenido <color=#00F6FF>Reanimación II</color>: Conviértete en invencible cuando su HP cae al 1% y restaura <color=#00F6FF>25%</color> de su HP máximo después.",
  str_n12_affix_des_5122410 = "Sin forma obtenido <color=#00F6FF>Reanimación III</color>: Conviértete en invencible cuando su HP cae al 1% y restaura <color=#00F6FF>40%</color> de su HP máximo después.",
  str_n12_affix_des_5122411 = "El daño de Formless infligido a los Aurorianos aumenta en porcentaje de acuerdo con el HP actual del objetivo. Cuanto menor sea el HP de un Aurorian, mayor será el DAÑO, hasta <color=#00F6FF>{1}</color> tiempos del DMG original.",
  str_n12_affix_des_5122413 = "El orden del grupo de habilidades de Formless cambió: Nonentity Feast se lanza durante la primera ronda",
  str_n12_affix_des_5122414 = "Formless se une a la batalla con <color=#00F6FF>{1}</color> montones de escudo de conteo.",
  str_n12_affix_des_5122417 = "La habilidad Invisible Flash de Formless obtuvo un nuevo efecto: invoca un abismo adicional en un lugar aleatorio dentro de 1 grupo circundante alrededor de los aurorianos.",
  str_n12_affix_des_5122418 = "El Aurorian en la posición de Capitán no puede atacar a menos que esté en una loseta de su elemento.",
  str_n12_affix_des_5122419 = "Sin forma obtenido <color=#00F6FF>Libre de daños I</color>: Cuando el daño de un solo ataque excede su HP máximo por <color=#00F6FF>15%</color>, el daño excedente se ignora.",
  str_n12_affix_des_5122420 = "Sin forma obtenido <color=#00F6FF>Libre de daños II</color>: Cuando el daño de un solo ataque excede su HP máximo por <color=#00F6FF>12%</color>, el daño excedente se ignora.",
  str_n12_affix_des_5122421 = "Sin forma obtenido <color=#00F6FF>Libre de daños III</color>: Cuando el daño de un solo ataque excede su HP máximo por <color=#00F6FF>8%</color>, el daño excedente se ignora.",
  str_n12_affix_des_5122422 = "Sin forma obtenido <color=#00F6FF>Carcasa dura I</color>: Solo el primero <color=#00F6FF>15</color> los ataques normales pueden causar daño.",
  str_n12_affix_des_5122423 = "Sin forma obtenido <color=#00F6FF>Carcasa dura II</color>: Solo el primero <color=#00F6FF>10</color> los ataques normales pueden causar daño.",
  str_n12_affix_des_5122424 = "Sin forma obtenido <color=#00F6FF>Carcasa dura III</color>: Solo el primero <color=#00F6FF>7</color> los ataques normales pueden causar daño.",
  str_n12_affix_des_5122425 = "Sin forma obtenido <color=#00F6FF>Fragilidad I</color>: El daño por quemadura sostenida, envenenamiento y sangrado aumenta a <color=#00F6FF>2</color> veces más que la cantidad regular.",
  str_n12_affix_des_5122426 = "Sin forma obtenido <color=#00F6FF>Fragilidad II</color>: El daño por quemadura sostenida, envenenamiento y sangrado aumenta a <color=#00F6FF>3</color> veces más que la cantidad normal.",
  str_n12_affix_des_5122427 = "Sin forma obtenido <color=#00F6FF>aurora eco</color>: Durante Aurora Time, su HP se restaura a lo que era al comienzo de la ronda.",
  str_n12_affix_des_10101 = "DEF y HP máximo de los jugadores de bolos -<color=#00F6FF>{1}%</color>",
  str_n12_affix_des_10102 = "El daño que sufren los jugadores de bolos de los combos en cadena es <color=#00F6FF>1.5</color> veces más que la cantidad normal.",
  str_n12_affix_des_10103 = "HP máximo de los jugadores de bolos +<color=#00F6FF>{1}%</color>",
  str_n12_affix_des_10104 = "Todos los Thumpers' DEF y Max HP +<color=#00F6FF>{1}%</color>",
  str_n12_affix_des_11104 = "Todos los Thumpers' DEF y Max HP +<color=#00F6FF>{1}%</color>, y Movilidad +1.",
  str_n12_affix_des_10105 = "Deathrider inflige daño adicional de <color=#00F6FF>{1}%</color> del Max HP a los Aurorianos.",
  str_n12_affix_des_10601 = "Crea 2 trampas adicionales de Bomb Generator",
  str_n12_affix_des_10701 = "Al comienzo de la batalla, suelta un Thumper que no pueda ser atacado.",
  str_n12_affix_des_10801 = "El daño que sufren los jugadores de bolos con ataques normales, combos y habilidades activas en su estado sobrio se reduce en <color=#00F6FF>{1}%</color>",
  str_n12_affix_des_10901 = "Los jugadores de bolos son inmunes al efecto Asustado.",
  str_n12_affix_des_11001 = "Los jugadores de bolos obtuvieron la Mejora I: En estado normal, aumenta el ATK de otros enemigos en <color=#00F6FF>3%</color> y Movilidad por <color=#00F6FF>1</color> punto. No acumulable con otros efectos del mismo tipo.",
  str_n12_affix_des_11002 = "Los jugadores de bolos obtuvieron la Mejora II: En estado normal, aumenta el ATK de otros enemigos en <color=#00F6FF>6%</color> y Movilidad por <color=#00F6FF>1</color> punto. No acumulable con otros efectos del mismo tipo.",
  str_n12_affix_des_11003 = "Los jugadores de bolos obtuvieron la Mejora III: En estado normal, aumenta el ATK de otros enemigos en <color=#00F6FF>5%</color> y Movilidad por <color=#00F6FF>2</color> punto. No acumulable con otros efectos del mismo tipo.",
  str_n12_affix_des_11101 = "Los jugadores de bolos obtuvieron Valiance I: su DEF aumenta a medida que su HP cae hasta <color=#00F6FF>1.5</color> veces de su DEF original.",
  str_n12_affix_des_11102 = "Los jugadores de bolos obtuvieron Valiance II: su DEF aumenta a medida que su HP cae hasta <color=#00F6FF>2</color> veces de su DEF original.",
  str_n12_affix_des_11103 = "Los jugadores de bolos obtuvieron Valiance III: su DEF aumenta a medida que su HP cae hasta <color=#00F6FF>2.5</color> veces de su DEF original.",
  str_n12_affix_des_11201 = "Bowlinger 680 obtuvo Dark Domain: En su estado sobrio, pierde 1 ronda extra al final de la ronda",
  str_n12_affix_des_11301 = "Los jugadores de bolos obtienen flujo oscuro persistente: en su estado normal, pueden causar daño al equipo cuando se mueven dentro de 1 grupo circundante de ellos.",
  str_n12_affix_des_51225011 = "ATK de Valencia -<color=#00F6FF>{1}%</color> y DEF -<color=#00F6FF>{2}%</color>.",
  str_n12_affix_des_51225021 = "ATK de Cañón láser I -<color=#00F6FF>{1}%</color>.",
  str_n12_affix_des_51225031 = "HP máximo de Valencia +<color=#00F6FF>{1}%</color>",
  str_n12_affix_des_51225061 = "El daño que sufre el Valencia de un ataque normal -<color=#00F6FF>{1}%</color>.",
  str_n12_affix_des_51225091 = "Cañón láser I actualizado a Cañón láser II: causa daño e inflige 2 acumulaciones de efecto de quemadura",
  str_n12_affix_des_51225101 = "Dragger I actualizado a Dragger II: esta trampa se activa nuevamente después de que todas las demás trampas completan su acción",
  str_n12_affix_des_51225111 = "Prism Tower I actualizó a Prism Tower II: los rayos láser se emiten en forma de Union Jack.",
  str_n12_affix_des_51225121 = "Jammer I actualizado a Jammer II: afecta un área más grande. Todas las fichas dentro de su rango están bloqueadas",
  str_n12_affix_des_51325131 = "HP de la Torre Prisma +<color=#00F6FF>{1}</color>",
  str_n12_affix_des_51325141 = "El daño de Valencia infligido a los Aurorianos aumenta en porcentaje de acuerdo con el HP actual del objetivo. Cuanto menor sea el HP de un Aurorian, mayor será el DAÑO, hasta <color=#00F6FF>{1}</color> tiempos del DMG original.",
  str_n12_affix_des_51325161 = "El daño de Valencia infligido a los Aurorianos aumenta en porcentaje de acuerdo con el HP actual del objetivo. Cuanto menor sea el HP de un Aurorian, mayor será el DAÑO, hasta <color=#00F6FF>{1}</color> tiempos del DMG original. Además, la movilidad de Valencia +<color=#00F6FF>{2}</color>",
  str_n12_affix_des_51325171 = "La condición de activación para todos los Combos en Cadena de Aurorianos +<color=#00F6FF>{1}</color>.",
  str_n12_affix_des_51325181 = "Valencia obtuvo Tenacidad I: Recibir <color=#00F6FF>3</color> acumulaciones de la marca de disminución de DMG por ronda, cada acumulación reduce el DAÑO de todos los tipos en <color=#00F6FF>10%</color>. <color=#00F6FF>1</color> la pila de la marca desaparece cada vez que sufre daño.",
  str_n12_affix_des_51325191 = "Valencia obtuvo Tenacidad II: Recibir <color=#00F6FF>5</color> acumulaciones de la marca de disminución de DMG por ronda, cada acumulación reduce el DAÑO de todos los tipos en <color=#00F6FF>7%</color>. <color=#00F6FF>1</color> la pila de la marca desaparece cada vez que sufre daño.",
  str_n12_affix_des_51325201 = "Valencia obtuvo Tenacidad III: Recibir <color=#00F6FF>7</color> acumulaciones de la marca de disminución de DMG por ronda, cada acumulación reduce el DAÑO de todos los tipos en <color=#00F6FF>6%</color>. <color=#00F6FF>1</color> la pila de la marca desaparece cada vez que sufre daño.",
  str_n12_affix_des_51325211 = "Valencia obtuvo Escudo Oscuro I: Recibir <color=#00F6FF>3</color> montones de escudo de conteo tan pronto como comience Aurora Time. El escudo desaparece al final de Aurora Time.",
  str_n12_affix_des_51325221 = "Valencia obtuvo Dark Shield II: Recibir <color=#00F6FF>8</color> montones de escudo de conteo tan pronto como comience Aurora Time. El escudo desaparece al final de Aurora Time.",
  str_n12_affix_des_51325231 = "Valencia obtuvo Dark Shield III: Recibir <color=#00F6FF>12</color> montones de escudo de conteo tan pronto como comience Aurora Time. El escudo desaparece al final de Aurora Time.",
