  str_n12_mission_sidename_11 = "Guiar",
  str_n12_mission_sidename_12 = "Furia",
  str_n12_mission_sidename_13 = "Diario",
  str_n12_mission_sidename_14 = "Persuasión",
  str_n12_mission_sidename_15 = "Peligro",
  str_n12_mission_sidename_16 = "En el cielo",
  str_n12_mission_sidename_17 = "Llamar",
  str_n12_mission_sidename_18 = "intercapitular",
  str_n12_1_desc_long = "El Coloso recibió una extraña señal. Mientras trataba de averiguar la fuente de la señal, el grupo cayó en un espacio increíble.",
  str_n12_2_desc_long = "Era una ciudad extraordinaria con bastantes guardias robot activos.\nSiobhan, un erudito de Illumina, sugirió cambiarse a un uniforme especial para evitar que los robots atacaran.",
  str_n12_3_desc_long = "Conociste a los compañeros de Siobhan, Florine y Erica de Lumópolis.\nEstos dos miembros de la División de Investigación de Herejes de Lumopolis parecían tener sus propios objetivos.\nSe formó un Equipo de Exploración ad hoc...",
  str_n12_4_desc_long = "La información fue compartida entre el grupo. Quedó claro que el lugar era una ciudad antigua en funcionamiento.\nDe alguna manera había cortado por completo el contacto con el mundo exterior y estaba bien mantenido por varias máquinas.\nPor otro lado, dos figuras misteriosas observaban la fiesta en la oscuridad...",
  str_n12_5_desc_long = "Mientras seguías la misteriosa fuente de la señal, el suelo empezó a temblar de nuevo y se acercaban más enemigos.\nPara sorpresa de todos, surgieron dos extrañas doncellas.\n¿Quiénes eran?",
  str_n12_6_desc_long = "¿Las dos jóvenes eran hijas del explorador Seamus de Illumina?\nDesafortunadamente, Seamus parecía haber fallecido.\nAntes de que pudiera aprender más, apareció una IA llamada Butler, que aconsejó al grupo que se alejara de los peligros potenciales...",
  str_n12_7_desc_long = "El mayordomo llevó al grupo a un distrito industrial relativamente seguro. El Valencia presentó brevemente su envidiable vida completamente automática.\nEl avance precipitado de Erica agravó la desconfianza de Gretel en el grupo. Se fue con Valencia.",
  str_n12_8_desc_long = "Después de rechazar algunos Eclipsites agresivos, Vice recibió otro mensaje encriptado de la transmisión de Seamus.\nEl grupo obtuvo una mejor idea de la situación y decodificó un conjunto de coordenadas de su mensaje.\n¡Deberíamos reunirnos con los demás lo antes posible y dirigirnos juntos al nuevo destino!",
  str_n12_9_desc_long = "Salvaste a dos aurorianos... Ruby y Rouge, integrantes de la Llave Rediesel.\nEllos revelaron que estabas bajo tierra y que el cielo arriba no era real.\nRuby le entregó un Comunicador para que pudiera mantenerse en contacto, y se fue con Rouge.",
  str_n12_10_desc_long = "Cerca del destino, intuiste que un buen número de Eclipsites se acercaban a Valencia y Gretel.\nSiobhan y Florine decidió acudir al rescate de las hermanas. El resto del grupo continuó hacia las coordenadas.\nLas dos hermanas ya estaban en una dura batalla. Cuando el Mayordomo estaba luchando para resistir a los Eclipsitas, la poderosa Lumina de Gretel estalló.",
  str_n12_11_desc_long = "Después de recibir Ruby y la llamada de socorro de Rouge, el grupo se reunió con éxito y fue a las coordenadas dejadas por Seamus.\nEra la habitación del Sr. y la Sra. Seamus, donde se guardaban algunos de sus registros encriptados.\nAdemás, descubriste un perro robótico interesante.",
  str_n12_12_desc_long = "Cuando todos ustedes estaban ocupados buscando en la habitación de Seamus, aparecieron Valencia y Gretel.\nLas hermanas enfurecidas ordenaron a los droides que te atacaran. Sorprendentemente, incluso los Eclipsites obedecieron sus órdenes.\nAfortunadamente, la ciudad estaba temblando de nuevo, lo que pareció afectar a Gretel. Aprovechaste esta oportunidad para escapar.",
  str_n12_13_desc_long = "Habiendo escapado de la ira de Valencia y Gretel, Siobhan logró descifrar el registro de Seamus.\nRegistraba su llegada a esta ciudad y su vida con el Mayordomo.\nApareció la pista final: ¡la única salida era a través del núcleo de energía en las profundidades de la ciudad!",
  str_n12_14_desc_long = "El grupo se dividió. Florine y algunos otros se adelantaron para verificar el plomo mientras Siobhan retrocedió contigo.\nNo podía dejar atrás a Valencia y Gretel en esta ciudad que se derrumbaba.",
  str_n12_15_desc_long = "Valencia se mostró escéptica ante tu historia mientras que Gretel se mantuvo salvajemente hostil hacia los extraños.\nSu ataque fue resistido, lo que la llevó al borde de un colapso una vez más. Toda la ciudad empezó a temblar...",
  str_n12_16_desc_long = "Valencia te impidió acercarte a Gretel colapsada y se produjo una feroz batalla.\nEventualmente, Siobhan convenció a Valencia de leer la carta que Seamus le había dejado.\nDespués de leer las últimas palabras de su padre, Valencia finalmente bajó la guardia y aceptó tu oferta de ayuda.\nSin embargo, Gretel y el Mayordomo se escabulleron mientras hablabas con Valencia...",
  str_n12_17_desc_long = "Todo el grupo prometió ayudar a Gretel. Valencia accedió a unirse.\nLlegaste a la ubicación objetivo en lo profundo de la ciudad, y la unidad de Florine ya había entrado.\nProbablemente Gretel también estaba allí abajo, tratando de proteger el núcleo de energía en esta precaria situación.\n¿Cómo se desarrollaría el resto de la historia? Continuará.",
  str_n12_18_desc_long = "En medio de otro terremoto, caíste en la oscuridad y estableciste una telepatía inesperada con el Mayordomo.\nRespondió muchas preguntas tuyas antes de mencionar una IA preocupante, Abby.",
  str_n12_intro_head_1 = "Obtención de reputación de investigación:",
  str_n12_intro_head_2 = "Descripción de la expedición diaria:",
  str_n12_intro_head_3 = "Descripción de la zona de peligro:",
  str_n12_intro_body_1 = "1. Durante el evento, completar las etapas de la Expedición diaria y cumplir con los requisitos de puntos en las Misiones de desafío de la Zona de peligro para obtener Reputación de investigación.\n2. La reputación de investigación obtenida se puede usar para desbloquear recompensas de notas de investigación e historias de eventos.",
  str_n12_intro_body_2 = "1. Las etapas de la Expedición diaria se dividen en 3 dificultades y los monstruos se actualizan diariamente. Completar con éxito las etapas otorga un elemento de evento: Reputación de investigación según la dificultad. Una vez superados, los navegadores pueden volver a intentar el mismo desafío para obtener más reputación de investigación hasta alcanzar el límite diario.\n2. Los navegadores comenzarán con un límite predeterminado de 2000 Reputación de investigación, seguido de un aumento de 2000 todos los días a partir de entonces hasta alcanzar el límite máximo de 16 000.",
  str_n12_intro_body_3 = "1. Hay 5 conjuntos de etapas de Zona de peligro, y los conjuntos se desbloquearán en secuencia todos los días. Una vez que se desbloquean las etapas, los navegantes pueden seleccionar el nivel de dificultad y los atributos para el desafío. Diferentes combinaciones de niveles de dificultad y atributos determinarán la experiencia de batalla y la puntuación de los Navegantes.\n2. Los 5 conjuntos de etapas se pueden desafiar repetidamente una vez que se desbloquean, y la puntuación más alta se calculará por separado y no se actualizará. Los puntajes están relacionados con las misiones de desafío en cada Zona de peligro y se basan en el puntaje de despeje más alto para cada nivel. Los Navegantes que completen las Misiones de Desafío especificadas recibirán la Reputación de Investigación correspondiente.",
  str_n12_entrust_stage_intro_title = "Guía del modo Dream Discovery",
  str_n12_entrust_stage_intro_head_1 = "Etapa desbloqueada",
  str_n12_entrust_stage_intro_head_2 = "Completar fase",
  str_n12_entrust_stage_intro_head_3 = "Recompensa de etapa",
  str_n12_entrust_stage_intro_body_1 = "1. Durante el evento, se desbloquea una etapa todos los días. Complete la etapa anterior para continuar.",
  str_n12_entrust_stage_intro_body_2 = "1. Una etapa se completa cuando llegas a su punto final. Después de completarlo, puedes quedarte para terminar otros eventos o salir del escenario.",
  str_n12_entrust_stage_intro_body_3 = "1. Obtenga materiales de mejora Lumamber, Nightium y Aurorian al llegar al punto final de cada etapa y cofres.",
  str_n12_challenge_diff = "Nivel de dificultad",
  str_n12_challenge_diff_desc = "(Cada nivel de dificultad tiene una puntuación base)",
  str_n12_affix_effect = "Bono de entrada",
  str_n12_affix_effect_desc = "(Cada entrada otorga puntos de bonificación)",
  str_n12_battle_cur_score = "Tu puntuación",
  str_n12_battle_record_max = "Mejor puntuación",
  str_n12_map_quest_x = "{1} X {2}",
  str_n12_map_get_rewards_title = "Compensación de recompensas obtenidas",
  str_n12_entrust_stage_task_1_1 = "Descubriste una huella extraña en un parterre cerca del edificio de la escuela, posiblemente dejada por algún pequeño droide.",
  str_n12_entrust_stage_task_1_2 = "¿Encontraste algún rastro del pequeño droide? Mira a tu alrededor más si no.",
